const writes = [];
await p.route(/supabase\.co/, (r) => {
  const u = r.request().url().replace(/^.*supabase\.co/, "");
  const meth = r.request().method();
  if (meth !== "GET" && meth !== "HEAD" && !/\/auth\//.test(u)) writes.push({ meth, u: decodeURIComponent(u), body: r.request().postData() });
  if (meth === "POST" && /\/rest\/v1\/algo_strategies/.test(u)) return r.fulfill({ status: 201, contentType: "application/json", body: JSON.stringify({ id: "new" + writes.length }) });
  if (/\/auth\/v1\/user/.test(u)) return r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ id: uid, email: me.email }) });
  const m = u.match(/\/rest\/v1\/(rpc\/[a-z_]+|[a-z_]+)/);
  const key = m && (m[1] === "lab_results_list" ? "lab_results" : m[1]);
  let body = key in res ? res[key] : [];
  if (key === "algo_signals" || key === "algo_backtests" || key === "lab_margins" || key === "algo_chart") body = [];
  const single = /application\/vnd\.pgrst\.object/.test(r.request().headers()["accept"] || "");
  if (single && Array.isArray(body)) body = body[0] ?? null;
  if (!(key in res) && !/algo_signals|algo_backtests|lab_margins|algo_chart/.test(u)) console.log("UNMOCKED", r.request().method(), u.slice(0, 100));
  r.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(body) });
});
